const listMessagesBefore = `-- name: ListMessagesBefore :many
SELECT m.id, m.channel_id, m.author_id, m.body, m.nonce, m.created_at, m.edited_at, m.deleted_at, m.deleted_by, m.attachments, m.has_files, u.display_name AS author_name, u.is_bot AS author_is_bot
FROM messages m
JOIN users u ON u.id = m.author_id
WHERE m.channel_id = $1
  AND m.deleted_at IS NULL
  AND ($2::uuid IS NULL OR m.id < $2::uuid)
ORDER BY m.id DESC
LIMIT $3
`

type ListMessagesBeforeParams struct {
	ChannelID pgtype.UUID `json:"channel_id"`
	Before    pgtype.UUID `json:"before"`
	RowLimit  int32       `json:"row_limit"`
}

type ListMessagesBeforeRow struct {
	ID          pgtype.UUID        `json:"id"`
	ChannelID   pgtype.UUID        `json:"channel_id"`
	AuthorID    pgtype.UUID        `json:"author_id"`
	Body        string             `json:"body"`
	Nonce       string             `json:"nonce"`
	CreatedAt   time.Time          `json:"created_at"`
	EditedAt    pgtype.Timestamptz `json:"edited_at"`
	DeletedAt   pgtype.Timestamptz `json:"deleted_at"`
	DeletedBy   pgtype.UUID        `json:"deleted_by"`
	Attachments []byte             `json:"attachments"`
	HasFiles    bool               `json:"has_files"`
	AuthorName  string             `json:"author_name"`
	AuthorIsBot bool               `json:"author_is_bot"`
}

// ListMessagesBefore returns up to row_limit messages of a channel older than
// the cursor (all when before is NULL), newest first, with their authors.
// Deleted messages are left out.
func (q *Queries) ListMessagesBefore(ctx context.Context, arg ListMessagesBeforeParams) ([]ListMessagesBeforeRow, error) {
	rows, err := q.db.Query(ctx, listMessagesBefore, arg.ChannelID, arg.Before, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListMessagesBeforeRow
	for rows.Next() {
		var i ListMessagesBeforeRow
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.AuthorID,
			&i.Body,
			&i.Nonce,
			&i.CreatedAt,
			&i.EditedAt,
			&i.DeletedAt,
			&i.DeletedBy,
			&i.Attachments,
			&i.HasFiles,
			&i.AuthorName,
			&i.AuthorIsBot,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markRead = `-- name: MarkRead :execrows
UPDATE channel_members SET last_read_id = $1
WHERE channel_id = $2 AND user_id = $3
  AND (last_read_id IS NULL OR last_read_id < $1)
`

type MarkReadParams struct {
	MessageID pgtype.UUID `json:"message_id"`
	ChannelID pgtype.UUID `json:"channel_id"`
	UserID    pgtype.UUID `json:"user_id"`
}

// MarkRead moves a member's read position forward (never back).
func (q *Queries) MarkRead(ctx context.Context, arg MarkReadParams) (int64, error) {
	result, err := q.db.Exec(ctx, markRead, arg.MessageID, arg.ChannelID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const purgeDeletedMessages = `-- name: PurgeDeletedMessages :execrows
DELETE FROM messages WHERE deleted_at <= now() - $1::interval
`

// PurgeDeletedMessages removes messages that can no longer be restored.
func (q *Queries) PurgeDeletedMessages(ctx context.Context, restoreWindow pgtype.Interval) (int64, error) {
	result, err := q.db.Exec(ctx, purgeDeletedMessages, restoreWindow)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

